const payload = $input.first().json.body;
const data = payload.data;

const isPass = data.percentage >= 60;
const summaryMessage = isPass 
  ? `Great job! You passed '${data.quizTitle}' with ${data.percentage}% accuracy (${data.score}/${data.totalQuestions}).`
  : `Good practice! You scored ${data.percentage}% on '${data.quizTitle}'. Review the missed concepts to strengthen recall.`;

return [{
  json: {
    userEmail: payload.userEmail,
    quizTitle: data.quizTitle,
    score: data.score,
    totalQuestions: data.totalQuestions,
    percentage: data.percentage,
    timeTakenSeconds: data.timeTakenSeconds,
    missedCount: data.missedQuestions ? data.missedQuestions.length : 0,
    summaryMessage
  }
}];
